/* The Black Market's rules (the trader and its screen are definitive_market_screen.c).
 *
 * The Exchange turns one rare item (a region's "<species> Core <numeral>", definitive_bestiary.c's second record) into
 * DEF_BM_COMMONS of the common Hunt Material the player picks: the owner's economy, where surplus rares refill the
 * commons the forge asks for in large amounts. It happens only when the whole lot fits under DEF_HUNT_MATERIAL_CAP, so
 * no exchange ever creates or destroys anything outside that rate.
 *
 * The Legendary Replicas (def_replicas, generated by tools/gen_replicas.py: equipment no shop sells) cost Bits and
 * one each of their own DEF_BM_REPLICA_RARES rare items, Rare Targets picked by the item's theme and strength (the
 * owner, 2026-11-17: what was hunted matters), so the screen names them and what is held of each. A replica is the item's own ID, so the card record keeps one bit per replica
 * (REC_EXTRA + 26..27), and while it is set the shops pay 0 for that ID (def_item_sell), an original held besides it
 * included: an accepted simplification. The bit clears once the player holds none of the ID, in the bag or
 * equipped (def_bm_sweep, every field frame), so a replica sold for nothing and a later original are told apart.
 *
 * Off in a replay script (def_on): nothing changes, every price is the game's. */
#include "common.h"
#include "gamestate.h"

#include "definitive.h"

extern int def_on(void); /* port.h declares it under PC_PORT only; the host test builds without it */
extern void port_log(const char *fmt, ...);

#define ITEM_SLOTS ((int)sizeof(gamestate_data.items)) /* the bag's counters, indexed by item ID */

int def_bm_held(int item) {
    if (item <= 0 || item >= ITEM_SLOTS) {
        return 0;
    }
    return gamestate_data.items[item] + gamestate_data.items_equipped[item];
}

int def_bm_replica_of(int item) {
    int r;

    for (r = 0; r < def_replica_count && r < DEF_REPLICAS; r++) {
        if (def_replicas[r].item == item) {
            return r;
        }
    }
    return -1;
}

int def_bm_resale_zero(int item) {
    int r;

    if (!def_on()) {
        return 0;
    }
    r = def_bm_replica_of(item);
    return r >= 0 && def_record_replica(r);
}

void def_bm_sweep(void) {
    int r;

    if (!def_on()) {
        return;
    }
    for (r = 0; r < def_replica_count && r < DEF_REPLICAS; r++) {
        if (def_record_replica(r) && def_bm_held(def_replicas[r].item) <= 0) {
            def_record_replica_set(r, 0);
            port_log("market: replica %d (item %d) no longer held: its resale is back", r, def_replicas[r].item);
        }
    }
}

/* ---- The Exchange */
int def_bm_exchange_check(int rare, int common) {
    if (!def_on()) {
        return DEF_BM_OFF;
    }
    if (rare < 0 || rare >= def_hunt_target_count || def_record_rare(rare) < 1) {
        return DEF_BM_NO_RARE;
    }
    if (common < 0 || common >= DEF_HUNT_MATERIALS ||
        def_record_material(common) + DEF_BM_COMMONS > DEF_HUNT_MATERIAL_CAP) {
        return DEF_BM_NO_ROOM;
    }
    return DEF_BM_OK;
}

int def_bm_exchange(int rare, int common) {
    int why = def_bm_exchange_check(rare, common);

    if (why != DEF_BM_OK) {
        return why;
    }
    def_record_rare_add(rare, -1);
    def_record_material_add(common, DEF_BM_COMMONS);
    port_log("market: rare %d for common %d x%d (now %d, rare left %d)", rare, common, DEF_BM_COMMONS,
             def_record_material(common), def_record_rare(rare));
    return DEF_BM_OK;
}

/* ---- The Legendary Replicas */
int def_hunt_mark_on(void) {
    return def_on() && gamestate_data.items[DEF_HUNT_MARK_ITEM] > 0;
}

int def_hunt_mark_mult(int n) {
    return def_hunt_mark_on() ? n * 2 : n;
}

int def_bm_replica_rows(void) {
    return (def_replica_count < DEF_REPLICAS ? def_replica_count : DEF_REPLICAS) + 1;
}

static int is_mark(int r) {
    return r == (def_replica_count < DEF_REPLICAS ? def_replica_count : DEF_REPLICAS);
}

int def_bm_replica_item(int r) {
    return is_mark(r) ? DEF_HUNT_MARK_ITEM : def_replicas[r].item;
}

int def_bm_replica_bits(int r) {
    return is_mark(r) ? DEF_HUNT_MARK_BITS : def_replicas[r].bits;
}

int def_bm_replica_owned(int r) {
    return is_mark(r) ? gamestate_data.items[DEF_HUNT_MARK_ITEM] > 0 : def_record_replica(r);
}

/* The Mark takes the rare items the player holds the most of (the ones he can best spare), each a different one. */
static int mark_pick(int picks[DEF_BM_REPLICA_RARES]) {
    int k, t, best, all = 1;

    for (k = 0; k < DEF_BM_REPLICA_RARES; k++) {
        best = -1;
        for (t = 0; t < def_hunt_target_count && t < DEF_HUNT_RARES; t++) {
            int again = 0, j;

            for (j = 0; j < k; j++) {
                again |= picks[j] == t;
            }
            if (!again && def_record_rare(t) > 0 && (best < 0 || def_record_rare(t) > def_record_rare(best))) {
                best = t;
            }
        }
        picks[k] = best;
        all &= best >= 0;
    }
    return all;
}

int def_bm_replica_pick(int r, int picks[DEF_BM_REPLICA_RARES]) {
    int k, all = 1;

    if (is_mark(r)) {
        return mark_pick(picks);
    }

    for (k = 0; k < DEF_BM_REPLICA_RARES; k++) {
        picks[k] = r >= 0 && r < def_replica_count ? def_replicas[r].cores[k] : -1;
        all &= picks[k] >= 0 && def_record_rare(picks[k]) >= 1;
    }
    return all;
}

int def_bm_replica_check(int r, int picks[DEF_BM_REPLICA_RARES]) {
    if (!def_on()) {
        return DEF_BM_OFF;
    }
    if (r < 0 || r >= def_bm_replica_rows()) {
        return DEF_BM_NO_CORES;
    }
    if (is_mark(r) && gamestate_data.items[DEF_HUNT_MARK_ITEM] > 0) {
        return DEF_BM_OWNED;
    }
    if (!def_bm_replica_pick(r, picks)) {
        return DEF_BM_NO_CORES;
    }
    if (gamestate_data.money < def_bm_replica_bits(r)) {
        return DEF_BM_NO_BITS;
    }
    if (gamestate_data.items[def_bm_replica_item(r)] >= DEF_BM_ITEM_CAP) {
        return DEF_BM_BAG_FULL;
    }
    return DEF_BM_OK;
}

int def_bm_replica_buy(int r) {
    int picks[DEF_BM_REPLICA_RARES], why = def_bm_replica_check(r, picks), k;

    if (why != DEF_BM_OK) {
        return why;
    }
    for (k = 0; k < DEF_BM_REPLICA_RARES; k++) {
        def_record_rare_add(picks[k], -1);
    }
    gamestate_data.money -= def_bm_replica_bits(r);
    gamestate_data.items[def_bm_replica_item(r)]++;
    if (!is_mark(r)) {
        def_record_replica_set(r, 1);
    }
    port_log("market: replica %d (item %d) for %d Bits and rares %d, %d", r, def_bm_replica_item(r), def_bm_replica_bits(r),
             picks[0], DEF_BM_REPLICA_RARES > 1 ? picks[DEF_BM_REPLICA_RARES - 1] : -1);
    return DEF_BM_OK;
}
